	greetings map[string]string
}

// NewGreetingService initializes the GreetingService with default greetings
func NewGreetingService() *GreetingService {
	return &GreetingService{
		client: &http.Client{
			Timeout: 5 * time.Second,
		},
		greetings: map[string]string{
