}

/* Typing animation */
@keyframes typing {
  0% { width: 0; }
  100% { width: 100%; }
}

@keyframes blink-caret {
  50% { border-color: transparent transparent; }
}

.typing-animation {
  overflow: hidden;
  border-right: 3px solid #007bff;
  white-space: nowrap;
  animation: 
    typing 3.5s steps(40, end),
    blink-caret 0.75s step-end infinite;
}

/* Alternative: Subtle input highlight */
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(0,123,255,0.4); }
  70% { box-shadow: 0 0 0(0,123,255,0.4); }
  100% { box-shadow: 0 0 0 0 rgba(0,123,255,0.4); }
}

.input-focused {
  animation: pulse 1s ease-in-out;
}
</style>
</head>
<body>

<form id="myForm">
  <div class="form-group">
    <input type="text" class="form-control" placeholder="Name" id="name">
  </div>
  <div class="form-group">
    <input type="email" class="form-control" placeholder="Email" id="email">
  </div>
  <div class="form-group">
    <textarea class="form-control" placeholder="Message"></textarea>
  </div>
</form>

<script>
// Add subtle animation on focus
document.querySelectorAll('.form-control').forEach(input => {
  input.addEventListener('focus', function() {
    this.classList.add('input-focused');
    setTimeout(() => this.classList.remove('input-focused'), 1000);
  });
});

// Optional: Add typing indicator during form completion
let typingTimer;
document.querySelectorAll('.form-control').forEach(input => {
  input.addEventListener('input', function() {
    clearTimeout(typingTimer);
    this.classList.add('typing');
    typingTimer = setTimeout(() => {
      this.classList.remove('typing');
    }, 1000);
  });
});
</script>

</body>
</html>
```

